BASE_REVISION = "15fe7d5011"
ARCHIVE_PREFIX = "rdf4j"
NEW_SOURCE_ROOT = "core/sail/lmdb/src"
DEFAULT_TASK_FILES = (
    "result-coordinate-execplan.md",
    "initial-evidence.txt",
    "result-coordinate-evidence/package-coordinate-deliverables.py",
    "result-coordinate-evidence/run-coordinate-experiments.py",
    "result-coordinate-evidence/freeze-experiment-classpath.py",
    "result-coordinate-evidence/ownership-validation-report.md",
    "result-coordinate-evidence/transport-design-report.md",
)
BLOCKED_DIRS = {
    ".git", ".m2_repo", ".m2", "target", "node_modules", "__pycache__",
    ".ssh", ".aws", ".azure", ".gnupg", ".kube", "credentials", "secrets",
}
CREDENTIAL_NAMES = {
    ".git-credentials", ".netrc", ".npmrc", ".pypirc",
    "credentials.json", "credentials.yaml", "credentials.yml",
    "secrets.json", "secrets.yaml", "secrets.yml",
}
STORE_SUFFIXES = {".mdb", ".hprof", ".heapdump", ".jfr", ".core"}
EVIDENCE_SUFFIXES = {".log", ".xml", ".json", ".jsonl", ".csv", ".md", ".py"}
SMALL_TEXT_SUFFIXES = {
    ".txt", ".tsv", ".out", ".err", ".patch", ".diff", ".sh", ".java",
    ".properties", ".yaml", ".yml", ".toml", ".rq", ".sparql", ".sql",
    ".dump", ".dumpstream",
}
EVIDENCE_BINARY_SUFFIXES = {
    ".jar", ".class", ".war", ".zip", ".gz", ".bz2", ".xz", ".zst",
    ".so", ".dll", ".dylib", ".o", ".a", ".pyc", ".bin", ".sqlite",
    ".sqlite3", ".db", ".dat", ".exe", ".png", ".jpg", ".jpeg", ".gif",
    ".pdf", ".woff", ".woff2", ".ttf",
} | STORE_SUFFIXES
CHUNK = 1024 * 1024


class PackageError(RuntimeError):
    pass


def require(condition: bool, message: str) -> None:
    if not condition:
        raise PackageError(message)


def json_bytes(value: Any) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True, ensure_ascii=True) + "\n").encode("utf-8")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(CHUNK), b""):
            digest.update(block)
    return digest.hexdigest()


def portable_path(value: str) -> str:
    path = PurePosixPath(value)
    require(bool(value) and not path.is_absolute() and ".." not in path.parts
            and "\\" not in value and "\0" not in value,
            f"Unsafe or nonportable archive path: {value!r}")
    require(path.as_posix() == value and value != ".", f"Noncanonical path: {value!r}")
    return value


def repo_relative(repo: Path, value: str) -> str:
    supplied = Path(value)
    # Resolve parents, but preserve a symlink at the final component for lstat.
    absolute = supplied if supplied.is_absolute() else repo / supplied
    absolute = absolute.parent.resolve(strict=True) / absolute.name
    try:
        return portable_path(absolute.relative_to(repo).as_posix())
    except ValueError as error:
        raise PackageError(f"Selected file must be inside the repository: {value}") from error


def exclusion(path: str, evidence: bool = False) -> str | None:
    parts = PurePosixPath(path).parts
    lower = tuple(part.casefold() for part in parts)
    if any(part in BLOCKED_DIRS for part in lower):
        return "build/cache/Git/credential directory"
    name = lower[-1]
    if name in CREDENTIAL_NAMES or name == ".env" or (
        name.startswith(".env.") and not name.endswith((".example", ".sample", ".template", ".dist"))
    ):
        return "credential or local environment file"
    if PurePosixPath(name).suffix in STORE_SUFFIXES or name in {"data.mdb", "lock.mdb"}:
        return "transient store, recording, or heap"
    if evidence:
        if any(part in {"classes", "test-classes"} or part.endswith("-classes") for part in lower):
            return "compiled class directory"
        if "artifacts" in lower and any(part == "frozen" or part.startswith("frozen-") for part in lower):
            return "frozen artifact object tree"
        if PurePosixPath(name).suffix in EVIDENCE_BINARY_SUFFIXES:
            return "binary artifact"
    return None


def clean_git_environment() -> dict[str, str]:
    environment = os.environ.copy()
    for name in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
                 "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_COMMON_DIR"):
        environment.pop(name, None)
    environment.update({"GIT_OPTIONAL_LOCKS": "0", "GIT_PAGER": "cat", "GIT_TERMINAL_PROMPT": "0"})
    return environment


class Git:
    def __init__(self, repo: Path):
        self.repo = repo.resolve()
        self.environment = clean_git_environment()
        top = Path(self.run(["rev-parse", "--show-toplevel"]).decode().strip()).resolve()
        require(top == self.repo, f"Not an initialized Git worktree: {repo}")
        self.object_format = self.run(["rev-parse", "--show-object-format"]).decode().strip()
        require(self.object_format in {"sha1", "sha256"}, "Unsupported Git object format")
        self.index_path = self.git_path("index")
        self.objects_path = self.git_path("objects")
        mode = self.run(["config", "--bool", "--get", "core.filemode"], allow_missing=True).strip()
        self.honor_filemode = mode != b"false"

    def git_path(self, item: str) -> Path:
        value = Path(self.run(["rev-parse", "--git-path", item]).decode().strip())
        return (value if value.is_absolute() else self.repo / value).resolve()

    def run(self, arguments: list[str], *, data: bytes | None = None,
            stdin: BinaryIO | None = None, stdout: BinaryIO | None = None,
            environment: dict[str, str] | None = None, allow_missing: bool = False) -> bytes:
        result = subprocess.run(
            ["git", "--no-pager", "-c", "core.splitIndex=false", "-c", "index.sparse=false",
             "-c", "core.fsmonitor=false", "-c", "core.untrackedCache=false",
             "-C", str(self.repo), *arguments],
            input=data, stdin=stdin, stdout=stdout if stdout is not None else subprocess.PIPE,
            stderr=subprocess.PIPE, env=environment or self.environment, check=False,
        )
        if result.returncode and not (allow_missing and result.returncode == 1):
            raise PackageError(f"Git {' '.join(arguments[:4])} failed: "
                               + result.stderr.decode("utf-8", "replace").strip())
        return result.stdout or b""

    def tracked(self) -> dict[str, tuple[str, str]]:
        entries = {}
        for record in self.run(["ls-files", "--stage", "-z"]).split(b"\0"):
            if not record:
                continue
            header, raw_path = record.split(b"\t", 1)
            mode, oid, stage = header.decode("ascii").split()
            path = portable_path(os.fsdecode(raw_path))
            require(stage == "0", f"Unresolved index stages at {path}")
            entries[path] = (mode, oid)
        return entries

    def tree(self, revision: str) -> dict[str, tuple[str, str]]:
        entries = {}
        for record in self.run(["ls-tree", "-r", "-z", revision]).split(b"\0"):
            if record:
                header, raw_path = record.split(b"\t", 1)
                mode, _kind, oid = header.decode("ascii").split()
                entries[portable_path(os.fsdecode(raw_path))] = (mode, oid)
        return entries

    def new_lmdb_files(self) -> set[str]:
        return {portable_path(os.fsdecode(path)) for path in self.run(
            ["ls-files", "--others", "--exclude-standard", "-z", "--", NEW_SOURCE_ROOT]
        ).split(b"\0") if path}


def index_signature(git: Git) -> tuple[bool, str | None]:
    return (True, sha256_file(git.index_path)) if git.index_path.exists() else (False, None)


def file_signature(path: Path) -> tuple[int, ...]:
    info = path.lstat()
    return (info.st_dev, info.st_ino, info.st_mode, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


@dataclass
class Candidate:
    path: str
    physical: Path
    category: str
    indexed_mode: str | None = None
    stage_root: bool = False
    honor_filemode: bool = True
    gitlink_oid: str | None = None


@dataclass
class Snapshot:
    path: str
    kind: str
    mode: str
    size: int
    sha256: str | None
    git_oid: str
    category: str
    stage_root: bool
    physical: Path
    signature: tuple[int, ...]
    spool: Path | None = None
    linkname: str | None = None

    def inventory(self) -> dict[str, Any]:
        result = {key: getattr(self, key) for key in
                  ("path", "kind", "mode", "size", "sha256", "git_oid", "category")}
        if self.linkname is not None:
            result["linkname"] = self.linkname
        return result


def collect_source(git: Git, explicit: set[str], allow_missing_submodules: bool,
                   verify_indexes: bool):
    candidates: dict[str, Candidate] = {}
    omissions: list[dict[str, str]] = []
    submodules: list[dict[str, Any]] = []
    repositories: list[Git] = []
    repository_states: dict[str, dict[str, Any]] = {}

    def collect(current: Git, prefix: str = "") -> None:
        repositories.append(current)
        index_before = index_signature(current) if verify_indexes else None
        tracked = current.tracked()
        head = current.run(["rev-parse", "--verify", "HEAD"]).decode().strip()
        require(not verify_indexes or index_signature(current) == index_before,
                f"Git index changed during source selection: {current.repo}")
        repository_states[str(current.repo)] = {"index": index_before, "tracked": tracked, "head": head}
        for local, (mode, oid) in tracked.items():
            path = prefix + local
            reason = exclusion(path)
            if reason:
                omissions.append({"path": path, "reason": reason})
                continue
            physical = current.repo / local
            if mode == "160000":
                initialized = (physical / ".git").exists()
                detail = {"path": path, "indexed_commit": oid, "initialized": initialized}
                config_key = f"submodule.{local}.url"
                detail["configured_url"] = current.run(
                    ["config", "-f", ".gitmodules", "--get", config_key], allow_missing=True
                ).decode("utf-8", "replace").strip() or None
                require(initialized or allow_missing_submodules,
                        f"Submodule {path} ({oid}) is not populated. Populate its exact source before packaging; "
                        "this script does not fetch. The explicit --allow-uninitialized-submodules option "
                        "produces a bundle with a documented external-source omission.")
                if initialized:
                    child = Git(physical)
                    require(not child.run(["status", "--porcelain=v1", "-z", "--untracked-files=no"]),
                            f"Tracked submodule worktree is dirty: {path}")
                    oid = child.run(["rev-parse", "HEAD"]).decode().strip()
                    detail["packaged_commit"] = oid
                    collect(child, path + "/")
                    require(repository_states[str(child.repo)]["head"] == oid,
                            f"Submodule HEAD changed during source selection: {path}")
                else:
                    require(physical.is_dir() and not any(physical.iterdir()),
                            f"Uninitialized submodule is not an empty directory: {path}")
                    detail["packaged_commit"] = None
                    detail["omission"] = "external submodule source unavailable; gitlink only"
                submodules.append(detail)
                candidates[path] = Candidate(path, physical, "gitlink", mode, not prefix,
                                             current.honor_filemode, oid)
            elif not physical.exists() and not physical.is_symlink():
                require(not prefix, f"Tracked submodule file is missing: {path}")
                omissions.append({"path": path, "reason": "tracked worktree deletion"})
            else:
                require(mode in {"100644", "100755", "120000"}, f"Unsupported tracked mode {mode}: {path}")
                candidates[path] = Candidate(path, physical, "tracked" if not prefix else "submodule-tracked",
                                             mode, not prefix, current.honor_filemode)

    collect(git)
    new_sources = git.new_lmdb_files()
    for path in sorted(new_sources | explicit):
        reason = exclusion(path)
        if reason:
            require(path not in explicit, f"Explicitly selected source is excluded: {path}: {reason}")
            omissions.append({"path": path, "reason": reason})
            continue
        physical = git.repo / path
        require(physical.exists() or physical.is_symlink(), f"Selected source is missing: {path}")
        require(not physical.is_dir(), f"Source selection must be an exact file, not a directory: {path}")
        if path not in candidates:
            require(not any(path.startswith(item["path"] + "/") for item in submodules),
                    f"Untracked files inside submodules require a clean tracked submodule commit: {path}")
            candidates[path] = Candidate(path, physical,
                                         "new-lmdb-source" if path in new_sources else "selected-task-file",
                                         stage_root=True)
    return candidates, omissions, submodules, repositories, new_sources, repository_states


def collect_evidence(repo: Path, roots: set[str], explicit: set[str], small_limit: int):
    candidates: dict[str, Candidate] = {}
    omissions: list[dict[str, str]] = []

    def add(path: str, requested: bool = False) -> None:
        reason = exclusion(path, evidence=True)
        physical = repo / path
        if reason:
            require(not requested, f"Explicit evidence is excluded: {path}: {reason}")
            omissions.append({"path": path, "reason": reason})
            return
        if physical.is_symlink():
            require(not requested, f"Evidence symlinks are not followed: {path}")
            omissions.append({"path": path, "reason": "evidence symlink"})
            return
        require(physical.exists(), f"Evidence is missing: {path}")
        require(physical.is_file(), f"Evidence selection is not a regular file: {path}")
        suffix = physical.suffix.casefold()
        if suffix not in EVIDENCE_SUFFIXES:
            if not requested and suffix not in SMALL_TEXT_SUFFIXES:
                omissions.append({"path": path, "reason": "suffix outside automatic evidence selection"})
                return
            if physical.stat().st_size > small_limit:
                require(not requested, f"Supporting evidence exceeds --small-text-bytes: {path}")
                omissions.append({"path": path, "reason": "large supplemental text; select explicitly with larger limit"})
                return
        candidates[path] = Candidate(path, physical, "selected-evidence" if requested else "task-evidence")

    for root in sorted(roots):
        physical_root = repo / root
        require(physical_root.is_dir() and not physical_root.is_symlink(), f"Evidence root is not a real directory: {root}")
        require(not exclusion(root, evidence=True), f"Excluded evidence root: {root}")
        for current, directories, files in os.walk(physical_root, followlinks=False):
            relative = Path(current).relative_to(repo)
            kept = []
            for directory in sorted(directories):
                child = (relative / directory).as_posix()
                reason = exclusion(child, evidence=True)
                if (Path(current) / directory).is_symlink():
                    reason = "directory symlink"
                if reason:
                    omissions.append({"path": child + "/", "reason": reason})
                else:
                    kept.append(directory)
            directories[:] = kept
            for name in sorted(files):
                add(portable_path((relative / name).as_posix()))
    for path in sorted(explicit):
        add(path, requested=True)
    return candidates, omissions


def snapshot(candidate: Candidate, repo: Path, cache: Path, number: int,
             object_format: str, text_only: bool = False) -> Snapshot:
    path = candidate.physical
    require(path.parent.resolve().is_relative_to(repo), f"Source parent escapes repository: {candidate.path}")
    before = file_signature(path)
    if candidate.gitlink_oid is not None:
        require(stat.S_ISDIR(before[2]), f"Gitlink is not a directory: {candidate.path}")
        return Snapshot(candidate.path, "gitlink", "160000", 0, None, candidate.gitlink_oid,
                        candidate.category, candidate.stage_root, path, before)
    symlink = stat.S_ISLNK(before[2])
    require(symlink or stat.S_ISREG(before[2]), f"Unsupported filesystem entry: {candidate.path}")
    require(not text_only or not symlink, f"Evidence symlink: {candidate.path}")
    if symlink:
        payload = os.fsencode(os.readlink(path))
        linkname = os.fsdecode(payload)
        target = posixpath.normpath(posixpath.join(posixpath.dirname(candidate.path), linkname))
        require(not posixpath.isabs(linkname) and target != ".." and not target.startswith("../")
                and "\\" not in linkname and "\0" not in linkname,
                f"Symlink escapes archive root: {candidate.path}")
        mode, kind, size = "120000", "symlink", len(payload)
    else:
        payload, linkname = None, None
        mode = "100755" if before[2] & 0o111 else "100644"
        if not candidate.honor_filemode and candidate.indexed_mode in {"100644", "100755"}:
            mode = candidate.indexed_mode
        kind, size = "file", before[3]
    blob = hashlib.new(object_format)
    blob.update(f"blob {size}\0".encode("ascii"))
    digest = hashlib.sha256()
    destination = cache / str(number)
    decoder = codecs.getincrementaldecoder("utf-8")("strict") if text_only else None

    def write(block: bytes, output: BinaryIO) -> None:
        if decoder is not None:
            require(b"\0" not in block, f"Binary NUL found in textual evidence: {candidate.path}")
            try:
                decoder.decode(block, final=False)
            except UnicodeDecodeError as error:
                raise PackageError(f"Evidence is not UTF-8 text: {candidate.path}") from error
        output.write(block)
        digest.update(block)
        blob.update(block)

    with destination.open("xb") as output:
        if symlink:
            write(payload, output)
        else:
            descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
            with os.fdopen(descriptor, "rb") as stream:
                opened = os.fstat(stream.fileno())
                require((opened.st_dev, opened.st_ino) == before[:2], f"File replaced before snapshot: {candidate.path}")
                for block in iter(lambda: stream.read(CHUNK), b""):
                    write(block, output)
        if decoder is not None:
            try:
                decoder.decode(b"", final=True)
            except UnicodeDecodeError as error:
                raise PackageError(f"Truncated UTF-8 evidence: {candidate.path}") from error
    require(file_signature(path) == before and destination.stat().st_size == size,
            f"File changed during snapshot: {candidate.path}")
    return Snapshot(candidate.path, kind, mode, size, digest.hexdigest(), blob.hexdigest(),
                    candidate.category, candidate.stage_root, path, before, destination, linkname)


def git_environment(git: Git, index: Path, objects: Path) -> dict[str, str]:
    environment = git.environment.copy()
    environment.update({"GIT_INDEX_FILE": str(index), "GIT_OBJECT_DIRECTORY": str(objects),
                        "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git.objects_path)})
    return environment


def publish_no_replace(staging: Path, output: Path) -> None:
    """Publish a verified directory atomically without replacing any existing path."""
    require(sys.platform.startswith("linux"), "Atomic nonreplacing publication requires Linux")
    libc = ctypes.CDLL(None, use_errno=True)
    rename = getattr(libc, "renameat2", None)
    require(rename is not None, "renameat2 is unavailable; no output directory has been replaced")
    rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    rename.restype = ctypes.c_int
    if rename(-100, os.fsencode(staging), -100, os.fsencode(output), 1):
        error = ctypes.get_errno()
        if error in {errno.EEXIST, errno.ENOTEMPTY}:
            raise PackageError(f"Output already exists; it was preserved: {output}")
        raise OSError(error, os.strerror(error), str(output))


def build_and_validate_patch(git: Git, base: str, entries: list[Snapshot], temporary: Path,
                             patch: Path) -> tuple[str, list[str]]:
    objects = temporary / "git-objects"
    objects.mkdir()
    environment = git_environment(git, temporary / "source.index", objects)
    git.run(["read-tree", base], environment=environment)
    baseline = git.tree(base)
    selected = {entry.path: entry for entry in entries if entry.stage_root}
    preserved_exclusions = sorted(path for path in baseline if exclusion(path))
    removals = sorted(path for path in baseline if path not in selected and not exclusion(path))
    if removals:
        git.run(["update-index", "--force-remove", "-z", "--stdin"],
                data=b"".join(os.fsencode(path) + b"\0" for path in removals), environment=environment)
    updates = []
    for path, entry in sorted(selected.items()):
        if entry.kind != "gitlink" and baseline.get(path, (None, None))[1] != entry.git_oid:
            with entry.spool.open("rb") as stream:
                written = git.run(["hash-object", "-w", "--stdin"], stdin=stream,
                                  environment=environment).decode().strip()
            require(written == entry.git_oid, f"Git blob hash mismatch: {path}")
        updates.append(entry.mode.encode() + b" " + entry.git_oid.encode() + b"\t" + os.fsencode(path) + b"\0")
    git.run(["update-index", "-z", "--index-info"], data=b"".join(updates), environment=environment)
    tree = git.run(["write-tree"], environment=environment).decode().strip()
    with patch.open("xb") as output:
        git.run(["diff", "--binary", "--full-index", "--no-color", "--no-ext-diff", "--no-textconv", "--no-renames",
                 "--src-prefix=a/", "--dst-prefix=b/", base, tree, "--"],
                stdout=output, environment=environment)
    verification = git_environment(git, temporary / "verification.index", objects)
    git.run(["read-tree", base], environment=verification)
    if patch.stat().st_size:
        git.run(["apply", "--cached", "--binary", "--whitespace=nowarn", str(patch)], environment=verification)
    actual = git.run(["write-tree"], environment=verification).decode().strip()
    require(actual == tree, f"Patch verification tree differs: wanted {tree}, got {actual}")
    return tree, preserved_exclusions


def write_archive(destination: Path, prefix: str, entries: list[Snapshot], manifest: bytes,
                  manifest_name: str, epoch: int) -> None:
    metadata_path = "__coordinate_package__/" + manifest_name
    validate_archive_namespace(entries)
    with destination.open("xb") as raw:
        with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=epoch) as compressed:
            with tarfile.open(mode="w|", fileobj=compressed, format=tarfile.PAX_FORMAT) as archive:
                for entry in sorted(entries, key=lambda item: item.path):
                    info = tarfile.TarInfo(prefix + "/" + entry.path)
                    info.uid = info.gid = 0
                    info.uname = info.gname = ""
                    info.mtime = epoch
                    if entry.kind == "gitlink":
                        info.type, info.mode, info.size = tarfile.DIRTYPE, 0o755, 0
                        archive.addfile(info)
                    elif entry.kind == "symlink":
                        info.type, info.mode, info.size = tarfile.SYMTYPE, 0o777, 0
                        info.linkname = entry.linkname
                        archive.addfile(info)
                    else:
                        info.mode = 0o755 if entry.mode == "100755" else 0o644
                        info.size = entry.size
                        with entry.spool.open("rb") as stream:
                            archive.addfile(info, stream)
                info = tarfile.TarInfo(prefix + "/" + metadata_path)
                info.uid = info.gid = 0
                info.uname = info.gname = ""
                info.mode, info.size, info.mtime = 0o644, len(manifest), epoch
                import io
                archive.addfile(info, io.BytesIO(manifest))


def validate_archive_namespace(entries: list[Snapshot]) -> None:
    selected = {entry.path: entry for entry in entries}
    require(len(selected) == len(entries), "Duplicate snapshot path")
    require(not any(path == "__coordinate_package__" or path.startswith("__coordinate_package__/")
                    for path in selected), "Reserved internal manifest namespace collides with source")
    for entry in entries:
        for parent in PurePosixPath(entry.path).parents:
            earlier = selected.get(parent.as_posix())
            require(earlier is None or earlier.kind == "gitlink",
                    f"Archive entry has a file or symlink parent: {entry.path}")
        if entry.kind != "symlink":
            continue
        resolved = list(PurePosixPath(entry.path).parent.parts)
        pending = deque(PurePosixPath(entry.linkname).parts)
        expansions = 0
        while pending:
            part = pending.popleft()
            if part in {"", "."}:
                continue
            if part == "..":
                require(bool(resolved), f"Transitive symlink escapes archive root: {entry.path}")
                resolved.pop()
                continue
            resolved.append(part)
            target = selected.get("/".join(resolved))
            if target is not None and target.kind == "symlink":
                expansions += 1
                require(expansions <= 40, f"Cyclic or excessively indirect archive symlink: {entry.path}")
                resolved.pop()
                pending.extendleft(reversed(PurePosixPath(target.linkname).parts))


def verify_archive(path: Path, prefix: str, entries: list[Snapshot], manifest: bytes, manifest_name: str) -> None:
    expected = {prefix + "/" + entry.path: entry for entry in entries}
    internal_name = prefix + "/__coordinate_package__/" + manifest_name
    seen: set[str] = set()
    with tarfile.open(path, "r:gz") as archive:
        for member in archive:
            name = portable_path(member.name.rstrip("/"))
            require(name not in seen, f"Duplicate archive member: {name}")
            seen.add(name)
            if name == internal_name:
                require(member.isfile(), "Internal manifest is not a regular file")
                with archive.extractfile(member) as stream:
                    require(stream.read() == manifest, "Internal manifest differs from external manifest")
                continue
            require(name in expected, f"Unexpected archive member: {name}")
            entry = expected[name]
            if entry.kind == "gitlink":
                require(member.isdir(), f"Gitlink marker is not a directory: {name}")
            elif entry.kind == "symlink":
                require(member.issym() and member.linkname == entry.linkname,
                        f"Symlink differs: {name}")
                require(hashlib.sha256(os.fsencode(member.linkname)).hexdigest() == entry.sha256,
                        f"Symlink hash differs: {name}")
            else:
                require(member.isfile() and member.size == entry.size, f"File size/type differs: {name}")
                require(member.mode == (0o755 if entry.mode == "100755" else 0o644), f"File mode differs: {name}")
                digest = hashlib.sha256()
                with archive.extractfile(member) as stream:
                    for block in iter(lambda: stream.read(CHUNK), b""):
                        digest.update(block)
                require(digest.hexdigest() == entry.sha256, f"Archive content hash differs: {name}")
    require(seen == set(expected) | {internal_name}, f"Archive coverage differs: {path.name}")


def read_selection(repo: Path, manifest_path: str | None, reports: list[str]):
    configuration: dict[str, Any] = {}
    if manifest_path:
        with Path(manifest_path).open(encoding="utf-8") as stream:
            configuration = json.load(stream)
        require(isinstance(configuration, dict), "Selection manifest must be a JSON object")
    allowed = {"source_include", "evidence_roots", "evidence_include", "reports"}
    require(not set(configuration) - allowed, "Unknown selection-manifest keys")
    for key, values in configuration.items():
        require(isinstance(values, list) and all(isinstance(item, str) for item in values),
                f"Manifest {key} must be an array of paths")
    source = {path for path in DEFAULT_TASK_FILES if (repo / path).is_file()}
    source.update(repo_relative(repo, value) for value in configuration.get("source_include", []))
    selected_reports = {repo_relative(repo, value) for value in [*reports, *configuration.get("reports", [])]}
    source.update(selected_reports)
    if manifest_path:
        candidate = Path(manifest_path).resolve()
        if candidate.is_relative_to(repo):
            source.add(portable_path(candidate.relative_to(repo).as_posix()))
    evidence = {repo_relative(repo, value) for value in configuration.get("evidence_include", [])}
    evidence.update(source)
    roots = {repo_relative(repo, value) for value in configuration.get("evidence_roots", ["result-coordinate-evidence"])}
    return source, roots, evidence, selected_reports


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parent.parent)
    parser.add_argument("--base", default=BASE_REVISION, help="Immutable patch base (default: 15fe7d5011)")
    parser.add_argument("--output", type=Path, default=Path("result-coordinate-deliverables"))
    parser.add_argument("--manifest", help="Explicit JSON selection manifest")
    parser.add_argument("--report", action="append", default=[], help="Exact repository report path; may repeat")
    parser.add_argument("--allow-uninitialized-submodules", action="store_true",
                        help="Explicitly permit and record missing external source; strict completeness is the default")
    parser.add_argument("--small-text-bytes", type=int, default=2 * 1024 * 1024)
    parser.add_argument("--mtime", type=int, default=0, help="Deterministic archive timestamp (default: 0)")
    parser.add_argument("--dry-run", action="store_true", help="Select and check paths without hashing, staging, or archiving")
    args = parser.parse_args()
    require(args.small_text_bytes > 0 and 0 <= args.mtime <= 0xFFFFFFFF, "Invalid size or archive timestamp")
    repo = args.repo.resolve(strict=True)
    output = args.output if args.output.is_absolute() else repo / args.output
    output = output.parent.resolve(strict=True) / output.name
    require(output != repo and not os.path.lexists(output),
            f"Output directory already exists or is the repository: {output}")
    git = Git(repo)
    base = git.run(["rev-parse", "--verify", args.base + "^{commit}"]).decode().strip()
    explicit, evidence_roots, evidence_explicit, reports = read_selection(repo, args.manifest, args.report)
    require(not any(output.is_relative_to(repo / root) for root in evidence_roots),
            "Output directory must be outside evidence roots")
    print("Selecting complete tracked source, new LMDB source, and task evidence", file=sys.stderr)
    source, source_omissions, submodules, repositories, new_sources, repository_states = collect_source(
        git, explicit, args.allow_uninitialized_submodules, not args.dry_run)
    evidence, evidence_omissions = collect_evidence(repo, evidence_roots, evidence_explicit, args.small_text_bytes)
    selection = {"base_commit": base, "source_include": sorted(explicit), "reports": sorted(reports),
                 "new_lmdb_source": sorted(new_sources), "evidence_roots": sorted(evidence_roots),
                 "evidence_include": sorted(evidence_explicit), "submodules": submodules,
                 "source_entries": len(source), "evidence_entries": len(evidence),
                 "source_omissions": source_omissions, "evidence_omissions": evidence_omissions}
    if args.dry_run:
        sys.stdout.buffer.write(json_bytes(selection))
        return 0
    staging: Path | None = None
    try:
        with tempfile.TemporaryDirectory(prefix="rdf4j-coordinate-package-") as location:
            temporary = Path(location)
            cache = temporary / "snapshot"
            cache.mkdir()
            all_snapshots: list[Snapshot] = []
            source_snapshot: list[Snapshot] = []
            evidence_snapshot: list[Snapshot] = []
            print(f"Snapshotting {len(source)} source entries and {len(evidence)} evidence files", file=sys.stderr)
            for candidates, destination, text_only in ((source, source_snapshot, False), (evidence, evidence_snapshot, True)):
                for candidate in sorted(candidates.values(), key=lambda item: item.path):
                    captured = snapshot(candidate, repo, cache, len(all_snapshots), git.object_format, text_only)
                    all_snapshots.append(captured)
                    destination.append(captured)
            staging = Path(tempfile.mkdtemp(prefix="coordinate-deliverables-staging-", dir=output.parent))
            print("Constructing isolated Git tree and verifying the binary patch", file=sys.stderr)
            tree, excluded_base = build_and_validate_patch(git, base, source_snapshot, temporary,
                                                          staging / "rdf4j-full.patch")
            complete_external = all(item["initialized"] for item in submodules)
            source_manifest = {
                "schema": 1, "base_commit": base, "snapshot_tree": tree,
                "archive_prefix": ARCHIVE_PREFIX,
                "git_object_format": git.object_format,
                "source_scope": "tracked-worktree-plus-selected-task-files",
                "all_external_submodule_sources_included": complete_external,
                "submodules": submodules, "omissions": source_omissions,
                "excluded_base_paths_left_unchanged_in_patch": excluded_base,
                "entries": [entry.inventory() for entry in source_snapshot],
            }
            evidence_manifest = {"schema": 1, "roots": sorted(evidence_roots),
                                 "archive_prefix": ARCHIVE_PREFIX,
                                 "automatic_suffixes": sorted(EVIDENCE_SUFFIXES),
                                 "supplemental_text_suffixes": sorted(SMALL_TEXT_SUFFIXES),
                                 "supplemental_text_maximum_bytes": args.small_text_bytes,
                                 "credential_exclusion_policy": "path and filename filters; no content redaction",
                                 "omissions": evidence_omissions,
                                 "entries": [entry.inventory() for entry in evidence_snapshot]}
            for name, value in (("source-manifest.json", source_manifest),
                                ("evidence-manifest.json", evidence_manifest),
                                ("selection-manifest.json", selection)):
                (staging / name).write_bytes(json_bytes(value))
            print("Creating and reading back both archives with exact entry/hash coverage checks", file=sys.stderr)
            for name, prefix, entries, manifest_name in (
                ("rdf4j-source.tar.gz", ARCHIVE_PREFIX, source_snapshot, "source-manifest.json"),
                ("rdf4j-evidence.tar.gz", ARCHIVE_PREFIX, evidence_snapshot, "evidence-manifest.json"),
            ):
                manifest = (staging / manifest_name).read_bytes()
                write_archive(staging / name, prefix, entries, manifest, manifest_name, args.mtime)
                verify_archive(staging / name, prefix, entries, manifest, manifest_name)
            for captured in all_snapshots:
                require(file_signature(captured.physical) == captured.signature,
                        f"Input changed after snapshot: {captured.path}; stop writers and rerun")
            for current in repositories:
                before = repository_states[str(current.repo)]
                require(current.tracked() == before["tracked"], "Tracked selection changed during packaging")
                require(index_signature(current) == before["index"],
                        f"A real Git index changed during packaging: {current.repo}")
                require(current.run(["rev-parse", "--verify", "HEAD"]).decode().strip() == before["head"],
                        f"Git HEAD changed during packaging: {current.repo}")
                if current is not git:
                    require(not current.run(["status", "--porcelain=v1", "-z", "--untracked-files=no"]),
                            f"Submodule changed during packaging: {current.repo}")
            require(git.new_lmdb_files() == new_sources, "New LMDB source selection changed during packaging")
            evidence_after, _ = collect_evidence(repo, evidence_roots, evidence_explicit, args.small_text_bytes)
            require(set(evidence_after) == set(evidence), "Evidence files appeared/disappeared during packaging")
            artifact_hashes = {path.name: {"sha256": sha256_file(path), "bytes": path.stat().st_size}
                               for path in sorted(staging.iterdir())}
            summary = {"schema": 1, "base_commit": base, "snapshot_tree": tree,
                       "archive_prefix": ARCHIVE_PREFIX,
                       "source_entries": len(source_snapshot), "evidence_entries": len(evidence_snapshot),
                       "all_external_submodule_sources_included": complete_external,
                       "patch_apply_tree_equality": True, "source_archive_verified": True,
                       "evidence_archive_verified": True, "real_indexes_unchanged": True,
                       "inputs_stable_through_verification": True, "artifacts": artifact_hashes}
            (staging / "package-summary.json").write_bytes(json_bytes(summary))
            checksums = []
            for path in sorted(staging.iterdir()):
                digest = sha256_file(path)
                checksums.append(f"{digest}  {path.name}\n")
                require(path.stat().st_size > 0 or path.name == "rdf4j-full.patch", f"Empty deliverable: {path.name}")
            (staging / "SHA256SUMS").write_text("".join(checksums), encoding="ascii")
            publish_no_replace(staging, output)
            staging = None
            print(f"Published verified deliverables: {output}")
            if not complete_external:
                print("External submodule source is incomplete; see source-manifest.json.", file=sys.stderr)
            return 0
    finally:
        if staging is not None:
            shutil.rmtree(staging)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (PackageError, OSError, ValueError, subprocess.SubprocessError) as error:
        print(f"Packaging failed: {error}", file=sys.stderr)
        raise SystemExit(1)
